  const g = new THREE.Group(), mats = [];
  const blue = new THREE.MeshStandardMaterial({ color: BLUE, roughness: 0.3, metalness: 0.02, transparent: true, opacity: 1, side: THREE.DoubleSide });
  const red = new THREE.MeshStandardMaterial({ color: RED, roughness: 0.3, metalness: 0.02, transparent: true, opacity: 1, side: THREE.DoubleSide });
  mats.push(blue, red);
  if (kind === 's') {
    g.add(new THREE.Mesh(new THREE.SphereGeometry(0.55, 40, 28), blue));
  } else {
    const ax = kind === 'px' ? CHEM(1, 0, 0) : kind === 'py' ? CHEM(0, 1, 0) : CHEM(0, 0, 1);
    const geo = lobeGeometry(1.9, 0.55);
    g.add(orient(new THREE.Mesh(geo, blue), ax));
    g.add(orient(new THREE.Mesh(geo, red), ax.clone().negate()));
  }
  return { group: g, mats };
}

/* ---------- hybrid builder (depends on toggles) ---------- */
function buildHybridSet(signs) {
  const g = new THREE.Group(), mats = [];
  const mk = () => {
    const m = new THREE.MeshStandardMaterial({
      color: ORANGE, emissive: 0xfbd37a, emissiveIntensity: 0.16,
      roughness: 0.32, metalness: 0.04, transparent: true, opacity: 0.95, side: THREE.DoubleSide
    });
    mats.push(m); return m;
  };
  const on = [state.showPx, state.showPy, state.showPz];
  const numP = on.filter(Boolean).length;
  const v = CHEM(signs[0] * (on[0] ? 1 : 0), signs[1] * (on[1] ? 1 : 0), signs[2] * (on[2] ? 1 : 0));

  if (numP === 0) {
    let big = null;
    if (state.showS) { big = new THREE.Mesh(new THREE.SphereGeometry(0.62, 36, 24), mk()); g.add(big); }
    return { group: g, mats, dir: null, big };
  }
  const dir = v.normalize();
  const bigLen = 2.1, bigW = 0.75;
  let r = state.showS ? 1 / (1 + numP) : 1;
  const big = orient(new THREE.Mesh(lobeGeometry(bigLen, bigW), mk()), dir);
  g.add(big);
  const back = orient(new THREE.Mesh(lobeGeometry(bigLen * r, bigW * (state.showS ? r : 1)), mk()), dir.clone().negate());
  g.add(back);

  const lm = new THREE.LineBasicMaterial({ color: GREYA, transparent: true, opacity: 0.95 });
  mats.push(lm);
  const guide = new THREE.Line(new THREE.BufferGeometry().setFromPoints([
    dir.clone().multiplyScalar(-0.55), dir.clone().multiplyScalar(2.1)
  ]), lm);
  g.add(guide);
  return { group: g, mats, dir, big };
}

/* ---------- panels (stages 1-3) ---------- */
const panelsGroup = new THREE.Group();
const panels = [];
const PANEL_L = 2.3, DX = 3.75, DY = 3.5;
const panelLabels = [];

PANEL_DEF.forEach((def, i) => {
  const off = SR.clone().multiplyScalar(DX * (i % 2 ? 1 : -1))
    .add(SU.clone().multiplyScalar(DY * (i < 2 ? 1 : -1)));
  const g = new THREE.Group(); g.position.copy(off);
  g.add(makeTriad(PANEL_L));
  const atomic = buildAtomic(def.kind);
  g.add(atomic.group);
  panelsGroup.add(g);

  const axl = [
    addLabel('<i style="font-family:serif">x</i>', off.clone().add(CHEM(1, 0, 0).multiplyScalar(PANEL_L + 0.42)), { fontSize: '13px', color: '#333' }),
    addLabel('<i style="font-family:serif">y</i>', off.clone().add(CHEM(0, 1, 0).multiplyScalar(PANEL_L + 0.42)), { fontSize: '13px', color: '#333' }),
    addLabel('<i style="font-family:serif">z</i>', off.clone().add(CHEM(0, 0, 1).multiplyScalar(PANEL_L + 0.42)), { fontSize: '13px', color: '#333' })
  ];
  const cap = addLabel(def.cap, off.clone().add(CHEM(0, 0, -1).multiplyScalar(PANEL_L + 0.55)),
    { fontSize: '15px', color: '#333' });
  panelLabels.push({ axes: axl, cap });
  panels.push({ index: i, def, group: g, offset: off, atomic, hybrid: null, atomicOn: true });
});

/* ---------- combined tetrahedral view (stage 4) ---------- */
const combinedGroup = new THREE.Group();
const COMB_L = 2.7;
combinedGroup.add(makeTriad(COMB_L));
combinedGroup.add(new THREE.Mesh(new THREE.SphereGeometry(0.07, 16, 12),
  new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.5 })));
const combHybrids = [];

const arcPts = [];
for (let i = 0; i <= 48; i++) {
  const t = i / 48;
  arcPts.push(TET[0].clone().lerp(TET[1], t).normalize().multiplyScalar(1.0));
}
const angleArc = new THREE.Line(new THREE.BufferGeometry().setFromPoints(arcPts),
  new THREE.LineBasicMaterial({ color: 0x333333 }));
combinedGroup.add(angleArc);
const angleMid = TET[0].clone().lerp(TET[1], 0.5).normalize().multiplyScalar(1.35);

const combLabels = {
  x: addLabel('<i style="font-family:serif">x</i>', CHEM(1, 0, 0).multiplyScalar(COMB_L + 0.45), { fontSize: '14px', color: '#333' }),
  y: addLabel('<i style="font-family:serif">y</i>', CHEM(0, 1, 0).multiplyScalar(COMB_L + 0.45), { fontSize: '14px', color: '#333' }),
  z: addLabel('<i style="font-family:serif">z</i>', CHEM(0, 0, 1).multiplyScalar(COMB_L + 0.45), { fontSize: '14px', color: '#333' }),
  cap: addLabel('four sp<sup>3</sup> hybrid orbitals', CHEM(0, 0, -1).multiplyScalar(COMB_L + 0.6), { fontSize: '14px', color: '#333' }),
  angle: addLabel('109.5°', angleMid, { fontSize: '13px', color: '#333', bold: true })
};

/* ---------- process arrows ---------- */
function blockArrow(from, dir, len) {
  const g = new THREE.Group();
  const mat = new THREE.MeshStandardMaterial({ color: GREY, roughness: 0.6, metalness: 0 });
  const d = dir.clone().normalize();
  const shaftLen = len * 0.62, headLen = len * 0.38;
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.14, shaftLen, 16), mat);
  shaft.position.copy(d).multiplyScalar(shaftLen / 2); orient(shaft, d); g.add(shaft);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.32, headLen, 20), mat);
  head.position.copy(d).multiplyScalar(shaftLen + headLen / 2); orient(head, d); g.add(head);
  g.position.copy(from);
  return g;
}
const hybFrom = SU.clone().multiplyScalar(4.5).add(SR.clone().multiplyScalar(-0.9));
const arrowHyb = blockArrow(hybFrom, SR, 1.9);
const hybLabel = addLabel('Hybridization',
  hybFrom.clone().add(SR.clone().multiplyScalar(0.95)).add(SU.clone().multiplyScalar(0.6)),
  { fontSize: '14px', color: '#333' });

const tetFrom = SU.clone().multiplyScalar(-4.6);
const arrowTet = blockArrow(tetFrom, SU.clone().negate(), 1.9);
const tetLabel = addLabel('Gives a tetrahedral<br>arrangement',
  tetFrom.clone().add(SU.clone().multiplyScalar(-0.95)).add(SR.clone().multiplyScalar(1.85)),
  { fontSize: '14px', color: '#333' });

const formulaLabel = addLabel('', new THREE.Vector3(0, 0, 0),
  { fontSize: '13px', color: '#7a4a00', background: 'rgba(255,255,255,0.85)', bold: true });

/* ---------- label visibility helper ---------- */
function setVis(entry, on) { if (entry) entry.div.style.visibility = on ? 'visible' : 'hidden'; }

/* ---------- formula text ---------- */
function formulaFor(signs, plain) {
  const n = ['p<sub>x</sub>', 'p<sub>y</sub>', 'p<sub>z</sub>'];
  const np = ['px', 'py', 'pz'];
  const names = plain ? np : n;
  const on = [state.showPx, state.showPy, state.showPz];
  const terms = []; let k = 0;
  if (state.showS) { terms.push('s'); k++; }
  for (let i = 0; i < 3; i++) if (on[i]) { k++; terms.push((signs[i] > 0 ? '+ ' : (plain ? '- ' : '&minus; ')) + names[i]); }
  if (!k) return plain ? '(nothing selected)' : '(nothing selected)';
  let body = terms.join(' ').replace(/^\+ /, '');
  const coeff = k === 4 ? (plain ? '1/2' : '½') : (k === 1 ? '' : (plain ? '1/\u221A' + k : '1/&radic;' + k));
  return coeff + '(' + body + ')';
}

/* ---------- scene composition ---------- */
function setInScene(obj, want) {
  const has = obj.parent === scene;
  if (want && !has) { scene.add(obj); return true; }
  if (!want && has) { scene.remove(obj); return true; }
  return false;
}

function rebuildHybrids() {
  panels.forEach(p => {
    if (p.hybrid) { p.group.remove(p.hybrid.group); disposeTree(p.hybrid.group); }
    p.hybrid = buildHybridSet(p.def.signs);
    p.group.add(p.hybrid.group);
  });
  combHybrids.forEach(h => { combinedGroup.remove(h.group); disposeTree(h.group); });
  combHybrids.length = 0;
  PANEL_DEF.forEach(def => {
    const h = buildHybridSet(def.signs);
    combinedGroup.add(h.group);
    combHybrids.push(h);
  });
}

function registerHybridInteractions() {
  clearInteractive();
  if (state.stage === 0) return;
  const list = state.stage <= 2
    ? panels.map(p => ({ mesh: p.hybrid.big, i: p.index, signs: p.def.signs }))
    : combHybrids.map((h, i) => ({ mesh: h.big, i, signs: PANEL_DEF[i].signs }));
  list.forEach(({ mesh, i, signs }) => {
    if (!mesh) return;
    registerInteractive(mesh, {
      title: 'sp³ hybrid h' + (i + 1),
      body: 'h' + (i + 1) + ' = ' + formulaFor(signs, true) +
        '. All four sp³ hybrids have identical shape and energy — only their direction differs, ' +
        'and the four directions are 109.47° apart. Click the lobe again to clear the highlight.',
      tooltip: 'Isolate hybrid h' + (i + 1),
      onClick: () => {
        state.selected = (state.selected === i) ? null : i;
        applyOpacity(); updateFormulaLabel();
      }
    });
  });
}

function applyOpacity() {
  const m = state.morph;
  panels.forEach(p => {
    const av = 1 - m;
    p.atomic.mats.forEach(mat => { mat.opacity = av; });
    p.atomic.group.visible = av > 0.02 && p.atomicOn;
    const dim = (state.selected !== null && state.selected !== p.index) ? 0.22 : 0.95;
    p.hybrid.mats.forEach(mat => { mat.opacity = dim * m; });
    p.hybrid.group.visible = m > 0.02;
    const s = 0.55 + 0.45 * m;
    p.hybrid.group.scale.setScalar(s);
  });
  combHybrids.forEach((h, i) => {
    const dim = (state.selected !== null && state.selected !== i) ? 0.22 : 0.95;
    h.mats.forEach(mat => { mat.opacity = dim; });
  });
}

function updateFormulaLabel() {
  if (state.selected === null) { setVis(formulaLabel, false); return; }
  const i = state.selected;
  const inPanel = state.stage <= 2;
  const owner = inPanel ? panels[i] : null;
  const h = inPanel ? panels[i].hybrid : combHybrids[i];
  const base = inPanel ? owner.offset.clone() : new THREE.Vector3();
  const dir = h.dir ? h.dir.clone() : CHEM(0, 0, 1);
  formulaLabel.pos.copy(base.add(dir.multiplyScalar(inPanel ? 2.0 : 2.5)));
  formulaLabel.div.innerHTML = 'h<sub>' + (i + 1) + '</sub> = ' + formulaFor(PANEL_DEF[i].signs, false);
  setVis(formulaLabel, state.stage > 0);
}

function updateLabels() {
  const st = state.stage;
  const onPanels = st <= 2;
  panels.forEach((p, i) => {
    const lab = panelLabels[i];
    lab.axes.forEach(a => setVis(a, onPanels));
    const capOn = onPanels && (st === 0 ? p.atomicOn : true);
    setVis(lab.cap, capOn);
    lab.cap.div.innerHTML = st === 0
      ? p.def.cap
      : 'sp<sup>3</sup> <i>h</i><sub>' + (i + 1) + '</sub>';
  });
  setVis(combLabels.x, st === 3); setVis(combLabels.y, st === 3);
  setVis(combLabels.z, st === 3); setVis(combLabels.cap, st === 3);
  setVis(combLabels.angle, st === 3 && state.showAngle);
  angleArc.visible = st === 3 && state.showAngle;
  setVis(hybLabel, st === 1);
  setVis(tetLabel, st === 2);
  updateFormulaLabel();
}

function refit() { if (!userMoved()) setCameraView(VIEW); }

function applyState(forceFit) {
  const st = state.stage;
  state.morphTarget = st === 0 ? 0 : 1;
  if (st === 3) state.morph = 1;
  panels[0].atomicOn = state.showS;
  panels[1].atomicOn = state.showPx;
  panels[2].atomicOn = state.showPy;
  panels[3].atomicOn = state.showPz;

  let changed = false;
  changed = setInScene(panelsGroup, st <= 2) || changed;
  changed = setInScene(combinedGroup, st === 3) || changed;
  changed = setInScene(arrowHyb, st === 1) || changed;
  changed = setInScene(arrowTet, st === 2) || changed;

  if (state.selected !== null && st === 0) state.selected = null;

  rebuildHybrids();
  registerHybridInteractions();
  applyOpacity();
  updateLabels();
  if (changed || forceFit) refit();
}

/* ---------- morph loop ---------- */
let _lastT = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _lastT) / 1000); _lastT = now;
  if (Math.abs(state.morph - state.morphTarget) > 0.002) {
    state.morph += (state.morphTarget - state.morph) * Math.min(1, dt * 5.0);
    applyOpacity();
  }
}
tick();

/* ---------- UI wiring ---------- */
document.getElementById('btnReset').style.display = '';

const stageBtns = Array.from(document.querySelectorAll('#stageBtns button'));
stageBtns.forEach(b => b.addEventListener('click', () => {
  stopPlay();
  state.stage = parseInt(b.dataset.stage, 10);
  if (state.stage === 0) state.morph = 0;
  syncUI(); applyState();
}));

const cbS = document.getElementById('cbS');
const cbPx = document.getElementById('cbPx');
const cbPy = document.getElementById('cbPy');
const cbPz = document.getElementById('cbPz');
const cbAngle = document.getElementById('cbAngle');
function bindCb(cb, key) {
  cb.addEventListener('change', () => { stopPlay(); state[key] = cb.checked; applyState(); });
}
bindCb(cbS, 'showS'); bindCb(cbPx, 'showPx'); bindCb(cbPy, 'showPy'); bindCb(cbPz, 'showPz');
cbAngle.addEventListener('change', () => { state.showAngle = cbAngle.checked; updateLabels(); });

function syncUI() {
  stageBtns.forEach(b => b.classList.toggle('active', parseInt(b.dataset.stage, 10) === state.stage));
  cbS.checked = state.showS; cbPx.checked = state.showPx;
  cbPy.checked = state.showPy; cbPz.checked = state.showPz;
  cbAngle.checked = state.showAngle;
}

/* ---------- guided tour ---------- */
const STEPS = [
  {
    title: '1 · Four atomic orbitals',
    text: 'One spherical s orbital and three mutually perpendicular p orbitals (p<sub>x</sub>, p<sub>y</sub>, p<sub>z</sub>) sit on the same nucleus — blue and red lobes mark opposite phases.',
    state: { stage: 0, showS: true, showPx: true, showPy: true, showPz: true, showAngle: false }
  },
  {
    title: '2 · Hybridization',
    text: 'Mathematically mixing the four wavefunctions destroys their individual identities; the blue/red lobes merge and recolor into orange hybrid shapes.',
    state: { stage: 1 }
  },
  {
    title: '3 · Four equivalent sp³ hybrids',
    text: 'Each hybrid is one large orange lobe with a small back-lobe. All four are identical in shape and energy, differing only in the direction they point.',
    state: { stage: 2 }
  },
  {
    title: '4 · Drop a p orbital',
    text: 'Turn off p<sub>z</sub>: the surviving mixture can only spread in the xy plane, so the tetrahedron collapses — every p orbital is required for 3D directionality.',
    state: { stage: 2, showPz: false }
  },
  {
    title: '5 · Tetrahedral arrangement',
    text: 'Superimposing all four restored hybrids on one axis set gives lobes aimed at the corners of a tetrahedron, 109.5° apart — the geometry behind CH<sub>4</sub>, NH<sub>3</sub> and H<sub>2</sub>O.',
    state: { stage: 3, showPz: true, showAngle: true }
  }
];
let stepIdx = 0;
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  Object.assign(state, s.state);
  if (state.stage === 0) state.morph = 0;
  stepTitle.innerHTML = s.title;
  stepText.innerHTML = s.text;
  syncUI(); applyState();
}
document.getElementById('btnPrev').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
document.getElementById('btnNext').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });

let playTimer = null;
const btnPlay = document.getElementById('btnPlay');
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; btnPlay.textContent = '▶ Play'; btnPlay.classList.remove('active'); }
}
btnPlay.addEventListener('click', () => {
  if (playTimer) { stopPlay(); return; }
  btnPlay.textContent = '❙❙ Pause'; btnPlay.classList.add('active');
  goToStep(0);
  playTimer = setInterval(() => {
    if (stepIdx >= STEPS.length - 1) { stopPlay(); return; }
    goToStep(stepIdx + 1);
  }, 4200);
});

/* ---------- init ---------- */
applyState(true);
setCameraView(VIEW);
goToStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

