  if (MODEL.type === 'p') return PNAME[[1, 0, 0].length && MODEL.dirs[i].findIndex(v => Math.abs(v) > 0.5)] + ' (unhybridized)';
  if (MODEL.type === 's') return '<i>s</i> (unhybridized)';
