  const dir = MODEL.dirs[i];
  let s = '<i>h</i><sub>' + (i + 1) + '</sub> = ' + coefStr(cs) + ' <i>s</i>';
  for (let k = 0; k < 3; k++) {
    const c = cp * dir[k];
