/* ---------- builders ---------- */
function buildAtomic(kind) {
  const g = new THREE.Group(), mats = [];
  const blue = new THREE.MeshStandardMaterial({ color: BLUE, roughness: 0.32, metalness: 0.02, transparent: true, opacity: 1, side: THREE.DoubleSide });
  const red = new THREE.MeshStandardMaterial({ color: RED, roughness: 0.32, metalness: 0.02, transparent: true, opacity: 1, side: THREE.DoubleSide });
  mats.push(blue, red);
  if (kind === 's') {
    g.add(new THREE.Mesh(new THREE.SphereGeometry(0.45, 40, 28), blue));
  } else {
    const ax = kind === 'px' ? CHEM(1, 0, 0) : kind === 'py' ? CHEM(0, 1, 0) : CHEM(0, 0, 1);
    const geo = lobeGeometry(1.75, 0.40);
    g.add(orient(new THREE.Mesh(geo, blue), ax));
    g.add(orient(new THREE.Mesh(geo, red), ax.clone().negate()));
