}

function backRatio(n) { if (n <= 0) return 0; return Math.max(0.12, (Math.sqrt(n) - 1) / (Math.sqrt(n) + 1)); }

function buildHybridLobe(dirWorld, n) {
  const g = new THREE.Group(), mats = [];
  const mk = () => {
    const m = new THREE.MeshStandardMaterial({
      color: ORANGE, emissive: 0xf3cd8a, emissiveIntensity: 0.14,
      roughness: 0.34, metalness: 0.03, transparent: true, opacity: 0.96, side: THREE.DoubleSide
