  };
  const L = 2.05, W = 0.52, r = backRatio(n);
  const big = orient(new THREE.Mesh(lobeGeometry(L, W), mk()), dirWorld);
  g.add(big);
  g.add(orient(new THREE.Mesh(lobeGeometry(L * r, W * Math.sqrt(r)), mk()), dirWorld.clone().negate()));
  const lm = new THREE.LineBasicMaterial({ color: GREYA, transparent: true, opacity: 0.95 });
  mats.push(lm);
  g.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([
    dirWorld.clone().multiplyScalar(-1.15), dirWorld.clone().multiplyScalar(L + 0.2)
