function buildPurePair(dirWorld) {
  const g = new THREE.Group(), mats = [];
  const blue = new THREE.MeshStandardMaterial({ color: BLUE, roughness: 0.32, transparent: true, opacity: 1, side: THREE.DoubleSide });
  const red = new THREE.MeshStandardMaterial({ color: RED, roughness: 0.32, transparent: true, opacity: 1, side: THREE.DoubleSide });
  mats.push(blue, red);
  const geo = lobeGeometry(1.75, 0.40);
  const big = orient(new THREE.Mesh(geo, blue), dirWorld);
  g.add(big);
  g.add(orient(new THREE.Mesh(geo, red), dirWorld.clone().negate()));
  return { group: g, mats, big };
}

/* ---------- panel labels ---------- */
function panelLabels(off, L, capHTML) {
