  const axes = [
    mk('<i style="font-family:Georgia,serif">x</i>', CHEM(1, 0, 0).multiplyScalar(L + 0.3), 14, 3, '16px'),
    mk('<i style="font-family:Georgia,serif">y</i>', CHEM(0, 1, 0).multiplyScalar(L + 0.3), 13, -7, '16px'),
    mk('<i style="font-family:Georgia,serif">z</i>', CHEM(0, 0, 1).multiplyScalar(L + 0.3), 3, -13, '16px')
  ];
  const cap = addLabel(capHTML, off.clone().add(CHEM(0, 0, -1).multiplyScalar(L + 0.42)),
