/* ---------- atomic panels (fixed 2×2 grid) ---------- */
const PANEL_L = 2.15, DX = 3.25, DY = 3.15;
const SLOT = [[-DX, DY], [DX, DY], [-DX, -DY], [DX, -DY]];
const ATOM_DEF = [
  { kind: 's', cap: '<i style="font-family:Georgia,serif">s</i>', key: 'showS' },
  { kind: 'px', cap: '<i style="font-family:Georgia,serif">p<sub>x</sub></i>', key: 'showPx' },
  { kind: 'py', cap: '<i style="font-family:Georgia,serif">p<sub>y</sub></i>', key: 'showPy' },
  { kind: 'pz', cap: '<i style="font-family:Georgia,serif">p<sub>z</sub></i>', key: 'showPz' }
];
const atomicGroup = new THREE.Group();
const atomicPanels = ATOM_DEF.map((def, i) => {
  const off = new THREE.Vector3(SLOT[i][0], SLOT[i][1], 0);
  const g = new THREE.Group(); g.position.copy(off);
  const tri = makeTriad(PANEL_L); g.add(tri.group);
  const orb = buildAtomic(def.kind); g.add(orb.group);
  atomicGroup.add(g);
  return { def, group: g, off, orb, tri, labels: panelLabels(off, PANEL_L, def.cap) };
});

/* ---------- hybrid panels (rebuilt from model) ---------- */
const hybridGroup = new THREE.Group();
const hybPanels = [];
const hybLabelSets = [];

function layoutFor(k) {
  if (k <= 1) return [new THREE.Vector3(0, 0, 0)];
  if (k === 2) return [new THREE.Vector3(-DX, 0, 0), new THREE.Vector3(DX, 0, 0)];
  if (k === 3) return [new THREE.Vector3(-DX, DY * 0.92, 0), new THREE.Vector3(DX, DY * 0.92, 0), new THREE.Vector3(0, -DY * 0.92, 0)];
  return SLOT.map(s => new THREE.Vector3(s[0], s[1], 0));
}
function hybCaption(i) {
  if (MODEL.type === 'p') return PNAME[MODEL.dirs[i].findIndex(v => Math.abs(v) > 0.5)];
  if (MODEL.type === 's') return '<i style="font-family:Georgia,serif">s</i>';
  const t = MODEL.type === 'sp3' ? 'sp<sup>3</sup>' : MODEL.type === 'sp2' ? 'sp<sup>2</sup>' : 'sp';
  return '<i style="font-family:Georgia,serif">' + t + ' h<sub>' + (i + 1) + '</sub></i>';
}

function rebuildHybridPanels() {
  hybLabelSets.forEach(l => { l.axes.forEach(removeLabel); removeLabel(l.cap); });
  hybLabelSets.length = 0;
  [...hybridGroup.children].forEach(c => { hybridGroup.remove(c); disposeTree(c); });
  hybPanels.length = 0;
  if (MODEL.type === 'none') return;
  const pos = layoutFor(MODEL.dirs.length);
  MODEL.dirs.forEach((dc, i) => {
    const off = pos[i] || new THREE.Vector3();
    const g = new THREE.Group(); g.position.copy(off);
    const tri = makeTriad(PANEL_L); g.add(tri.group);
    let part, dirW = null;
    if (MODEL.type === 's') {
      const m = new THREE.MeshStandardMaterial({ color: ORANGE, emissive: 0xf3cd8a, emissiveIntensity: 0.14, roughness: 0.34, transparent: true, opacity: 0.96 });
      const sph = new THREE.Mesh(new THREE.SphereGeometry(0.5, 36, 24), m);
      const grp = new THREE.Group(); grp.add(sph);
      part = { group: grp, mats: [m], big: sph };
    } else {
      dirW = CHEM(dc[0], dc[1], dc[2]).normalize();
      part = MODEL.type === 'p' ? buildPurePair(dirW) : buildHybridLobe(dirW, MODEL.n);
