/* ---------- combined view ---------- */
const combinedGroup = new THREE.Group();
const COMB_L = 2.6;
const combTri = makeTriad(COMB_L); combinedGroup.add(combTri.group);
combinedGroup.add(new THREE.Mesh(new THREE.SphereGeometry(0.065, 16, 12),
  new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.5 })));
const combHyb = [];
let angleArc = null;
const combLabels = {
  x: addLabel('<i style="font-family:Georgia,serif">x</i>', CHEM(1, 0, 0).multiplyScalar(COMB_L + 0.3), { fontSize: '17px', color: '#151515', offset: [14, 3] }),
  y: addLabel('<i style="font-family:Georgia,serif">y</i>', CHEM(0, 1, 0).multiplyScalar(COMB_L + 0.3), { fontSize: '17px', color: '#151515', offset: [13, -7] }),
  z: addLabel('<i style="font-family:Georgia,serif">z</i>', CHEM(0, 0, 1).multiplyScalar(COMB_L + 0.3), { fontSize: '17px', color: '#151515', offset: [3, -13] }),
  cap: addLabel('', CHEM(0, 0, -1).multiplyScalar(COMB_L + 0.42), { fontSize: '18px', color: '#151515', offset: [0, 16] }),
  angle: addLabel('', new THREE.Vector3(0, 0, 0), { fontSize: '16px', color: '#222', bold: true, background: 'rgba(255,255,255,0.85)' })
