function rebuildCombined() {
  combHyb.forEach(h => { combinedGroup.remove(h.group); disposeTree(h.group); });
  combHyb.length = 0;
  if (angleArc) { combinedGroup.remove(angleArc); disposeTree(angleArc); angleArc = null; }
  if (MODEL.type === 'none') { combLabels.cap.div.innerHTML = 'nothing selected'; return; }
  if (MODEL.type === 's') {
    const m = new THREE.MeshStandardMaterial({ color: ORANGE, emissive: 0xf3cd8a, emissiveIntensity: 0.14, roughness: 0.34, transparent: true, opacity: 0.96 });
    const sph = new THREE.Mesh(new THREE.SphereGeometry(0.5, 36, 24), m);
