/* ---------- process arrows ---------- */
function blockArrow(from, dir, len) {
  const g = new THREE.Group();
  const mat = new THREE.MeshStandardMaterial({ color: GREY, roughness: 0.6 });
  const dd = dir.clone().normalize();
  const shaftLen = len * 0.62, headLen = len * 0.38;
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.11, shaftLen, 16), mat);
  shaft.position.copy(dd).multiplyScalar(shaftLen / 2); orient(shaft, dd); g.add(shaft);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.26, headLen, 20), mat);
  head.position.copy(dd).multiplyScalar(shaftLen + headLen / 2); orient(head, dd); g.add(head);
  g.position.copy(from);
