}
const arrowHyb = blockArrow(new THREE.Vector3(-0.8, 0, 0), new THREE.Vector3(1, 0, 0), 1.6);
const hybLabel = addLabel('Hybridization', new THREE.Vector3(0, 0.62, 0),
  { fontSize: '17px', color: '#151515', background: 'rgba(255,255,255,0.9)' });
const arrowTet = blockArrow(new THREE.Vector3(0, 0.8, 0), new THREE.Vector3(0, -1, 0), 1.6);
const tetLabel = addLabel('Gives a tetrahedral<br>arrangement', new THREE.Vector3(1.05, -0.35, 0),
  { fontSize: '16px', color: '#151515', background: 'rgba(255,255,255,0.9)' });

const formulaLabel = addLabel('', new THREE.Vector3(0, 0, 0),
  { fontSize: '14px', color: '#7a4a00', background: 'rgba(255,255,255,0.92)', bold: true });

/* ---------- picking (screen-space: reliable under the oblique shear) ------ */
const pickables = [];
function screenOf(p) {
  const v = p.clone().project(camera);
  return { x: (v.x * 0.5 + 0.5) * canvas.clientWidth, y: (-v.y * 0.5 + 0.5) * canvas.clientHeight };
}
function refreshPickables() {
  pickables.length = 0;
  if (MODEL.type === 'none' || MODEL.type === 's') return;
  if (state.stage === 0) return;
  if (state.stage === 1 && state.morph < 0.45) return;
  const src = state.stage === 3 ? combHyb : hybPanels;
  src.forEach(h => {
    if (!h.dir) return;
    const base = h.off ? h.off.clone() : new THREE.Vector3();
    pickables.push({
      pos: base.add(h.dir.clone().multiplyScalar(1.15)),
      idx: h.idx,
      name: MODEL.type === 'p' ? 'this p orbital' : 'hybrid h' + (h.idx + 1)
    });
  });
}
function pickAt(ev) {
  if (!pickables.length) return null;
  const rect = canvas.getBoundingClientRect();
  const mx = ev.clientX - rect.left, my = ev.clientY - rect.top;
  let best = null, bd = 52;
  for (const p of pickables) {
    const s = screenOf(p.pos);
    const dd = Math.hypot(s.x - mx, s.y - my);
    if (dd < bd) { bd = dd; best = p; }
  }
  return best;
}
let dragPx = 0, downX = 0, downY = 0, isDown = false;
canvas.addEventListener('pointerdown', e => { isDown = true; dragPx = 0; downX = e.clientX; downY = e.clientY; });
window.addEventListener('pointerup', () => { isDown = false; });
canvas.addEventListener('pointermove', e => {
  if (isDown) dragPx = Math.hypot(e.clientX - downX, e.clientY - downY);
  const p = pickAt(e);
  if (p) { canvas.style.cursor = 'pointer'; showTooltip('Click to isolate ' + p.name, e); }
});
canvas.addEventListener('click', e => {
  if (dragPx > 6) return;
  const p = pickAt(e);
  if (!p) return;
  state.selected = (state.selected === p.idx) ? null : p.idx;
  if (state.selected !== null) {
    showPopup(MODEL.type === 'p' ? 'Unhybridized p orbital' : 'Hybrid orbital h' + (p.idx + 1),
      formulaPlain(p.idx) + '.  ' + MODEL.note + ' Click the lobe again to clear the highlight.');
  } else hidePopup();
