/* ---------- opacity / visibility ---------- */
function applyOpacity() {
  const m = state.morph;
  const aOp = state.stage === 0 ? 1 : (state.stage === 1 ? 1 - m : 0);
  const hOp = state.stage === 0 ? 0 : (state.stage === 1 ? m : 1);

  atomicPanels.forEach((p, i) => {
    const on = state[p.def.key] ? 1 : 0;
    const o = aOp * on;
    p.orb.mats.forEach(mt => { mt.opacity = o; });
    p.tri.mats.forEach(mt => { mt.opacity = o; });
    p.group.visible = o > 0.02;
    p.labels.axes.forEach(l => setOp(l, o));
    setOp(p.labels.cap, o);
  });

  hybPanels.forEach((h, i) => {
    const dim = (state.selected !== null && state.selected !== h.idx) ? 0.22 : 1;
    h.orbMats.forEach(mt => { mt.opacity = 0.96 * dim * hOp; });
    h.tri.mats.forEach(mt => { mt.opacity = hOp; });
    h.group.visible = hOp > 0.02;
    const s = 0.62 + 0.38 * (state.stage === 1 ? m : 1);
    h.group.scale.setScalar(s);
    const L = hybLabelSets[i];
    if (L) { L.axes.forEach(l => setOp(l, hOp)); setOp(L.cap, hOp); }
  });

  combHyb.forEach(h => {
    const dim = (state.selected !== null && state.selected !== h.idx) ? 0.22 : 1;
    h.mats.forEach(mt => { mt.opacity = 0.96 * dim; });
  });
}

function updateFormulaLabel() {
  if (state.selected === null || MODEL.type === 'none' || state.stage === 0) { setOp(formulaLabel, 0); return; }
  const inPanel = state.stage <= 2;
  const list = inPanel ? hybPanels : combHyb;
  const h = list.find(e => e.idx === state.selected);
  if (!h) { setOp(formulaLabel, 0); return; }
  const base = h.off ? h.off.clone() : new THREE.Vector3();
  const dir = h.dir ? h.dir.clone() : CHEM(0, 0, 1);
  formulaLabel.pos.copy(base.add(dir.multiplyScalar(inPanel ? 2.35 : 2.9)));
  formulaLabel.div.innerHTML = formulaHTML(state.selected);
  setOp(formulaLabel, 1);
}

function updateSceneLabels() {
  const st = state.stage;
  setOp(combLabels.x, st === 3 ? 1 : 0);
  setOp(combLabels.y, st === 3 ? 1 : 0);
  setOp(combLabels.z, st === 3 ? 1 : 0);
  setOp(combLabels.cap, st === 3 ? 1 : 0);
  const showArc = st === 3 && state.showAngle && !!angleArc;
  setOp(combLabels.angle, showArc ? 1 : 0);
  if (angleArc) angleArc.visible = showArc;
  setOp(hybLabel, st === 1 ? 1 : 0);
  setOp(tetLabel, st === 2 ? 1 : 0);
  updateFormulaLabel();
}

/* ---------- scene composition ---------- */
function setInScene(obj, want) {
  const has = obj.parent === scene;
  if (want && !has) { scene.add(obj); return true; }
  if (!want && has) { scene.remove(obj); return true; }
  return false;
}
function refit() { if (!userMoved()) setCameraView(VIEW); }

function applyStage(opts = {}) {
  const st = state.stage;
  if (!opts.keepMorph) state.morphTarget = st === 0 ? 0 : 1;
  if (st >= 2) state.morph = 1;
  if (st === 0) { state.morph = 0; state.selected = null; }

  let changed = false;
  changed = setInScene(atomicGroup, st <= 1) || changed;
  changed = setInScene(hybridGroup, st === 1 || st === 2) || changed;
  changed = setInScene(combinedGroup, st === 3) || changed;
  changed = setInScene(arrowHyb, st === 1) || changed;
  changed = setInScene(arrowTet, st === 2) || changed;

  applyOpacity();
  updateSceneLabels();
  refreshPickables();
  if (changed || opts.forceFit) refit();
}

function syncModel(opts = {}) {
  MODEL = buildModel();
  if (state.selected !== null && state.selected >= MODEL.dirs.length) state.selected = null;
  rebuildHybridPanels();
  rebuildCombined();
  const n = MODEL.n;
  const mix = (state.showS ? 's' : '') + (state.showS && n ? ' + ' : '') + (n ? n + 'p' : '');
  document.getElementById('typeOut').innerHTML = (mix || '—') + ' → ' + MODEL.label +
    (MODEL.angle !== null ? ' · ' + angleText() : '');
  document.getElementById('typeNote').textContent = MODEL.note;
  applyStage(opts);
}

/* ---------- morph animation ---------- */
const mixSlider = document.getElementById('mix');
const mixOut = document.getElementById('mixOut');
let _lastT = performance.now();
(function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _lastT) / 1000); _lastT = now;
  if (Math.abs(state.morph - state.morphTarget) > 0.002) {
    state.morph += (state.morphTarget - state.morph) * Math.min(1, dt * 5.0);
    applyOpacity();
    refreshPickables();
    mixSlider.value = String(Math.round(state.morph * 100));
    mixOut.textContent = Math.round(state.morph * 100) + '%';
  }
})();

