/* ---------- guided tour ---------- */
const STEPS = [
  {
    title: '1 · Four atomic orbitals',
    text: 'One spherical <i>s</i> orbital and three mutually perpendicular <i>p</i> orbitals (<i>p<sub>x</sub></i>, <i>p<sub>y</sub></i>, <i>p<sub>z</sub></i>) on the same atom. Blue and red lobes are the two phases of the wavefunction.',
    st: { stage: 0, showS: true, showPx: true, showPy: true, showPz: true, showAngle: false }
  },
  {
    title: '2 · Hybridization',
    text: 'Adding and subtracting the four wavefunctions destroys their individual identities: the blue/red set fades out and four orange hybrids fade in. Drag the <b>Mixing</b> slider to do it by hand.',
    st: { stage: 1, showS: true, showPx: true, showPy: true, showPz: true }
  },
  {
    title: '3 · Four equivalent sp³ hybrids',
    text: 'Each hybrid is one big lobe plus a small back-lobe, h<sub>i</sub> = ½(<i>s</i> ± <i>p<sub>x</sub></i> ± <i>p<sub>y</sub></i> ± <i>p<sub>z</sub></i>). All four have identical shape and energy — only their direction differs.',
    st: { stage: 2, showS: true, showPx: true, showPy: true, showPz: true }
  },
  {
    title: '4 · Mix fewer p orbitals',
    text: 'Leave <i>p<sub>z</sub></i> out: <i>s</i> + two <i>p</i> gives <b>three sp² hybrids at 120°</b> in the <i>xy</i> plane (trigonal planar). Drop <i>p<sub>y</sub></i> too and you get <b>two sp hybrids at 180°</b> (linear). The number of hybrids always equals the number of orbitals mixed.',
    st: { stage: 2, showS: true, showPx: true, showPy: true, showPz: false }
  },
  {
    title: '5 · Tetrahedral arrangement',
    text: 'Restore <i>p<sub>z</sub></i> and superimpose all four hybrids on one axis set: the lobes point at the corners of a tetrahedron, 109.5° apart — the geometry behind CH₄, NH₃ and H₂O.',
    st: { stage: 3, showS: true, showPx: true, showPy: true, showPz: true, showAngle: true }
  }
];
let stepIdx = 0;
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  Object.assign(state, s.st);
  state.selected = null;
  state.morph = state.stage === 0 ? 0 : (state.stage === 1 ? state.morph : 1);
  stepTitle.innerHTML = s.title;
  stepText.innerHTML = s.text;
  syncUI();
  syncModel({ forceFit: true });
}
document.getElementById('btnPrev').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
document.getElementById('btnNext').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });

let playTimer = null;
const btnPlay = document.getElementById('btnPlay');
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; btnPlay.textContent = '▶ Play'; btnPlay.classList.remove('active'); }
}
btnPlay.addEventListener('click', () => {
  if (playTimer) { stopPlay(); return; }
  btnPlay.textContent = '❙❙ Pause'; btnPlay.classList.add('active');
  goToStep(0);
  playTimer = setInterval(() => {
    if (stepIdx >= STEPS.length - 1) { stopPlay(); return; }
    goToStep(stepIdx + 1);
  }, 4600);
});

/* ---------- init ---------- */
syncModel({ forceFit: true });
setCameraView(VIEW);
goToStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

