<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ---------- element spec -------------------------------------------------
   axis line        → CylinderGeometry(r .035, len 2L)  black  MeshBasic
   axis arrowhead   → ConeGeometry(.105,.30)            black
   axis label       → addLabel italic serif  x / y / z
   s orbital        → SphereGeometry(.42)               blue, baked shading
   p lobe (+axis)   → LatheGeometry teardrop len 1.70 halfW .42  blue
   p lobe (-axis)   → same geometry                                red
   panel caption    → addLabel italic serif  s / p_x / p_y / p_z
   hybrid big lobe  → LatheGeometry len 1.95 halfW .52  orange
   hybrid back lobe → LatheGeometry len 1.95*r halfW .52*sqrt(r)  orange
   hybrid guide line→ Line grey through the lobe axis
   process arrows   → Cylinder shaft .13 + Cone head .32/.72  grey
   angle arc        → Line of slerped points r 1.15 + label
   projection       → oblique (front-on, shear 35°, depth .60)
   layout           → 2x2 atomic block · arrow · 2x2 hybrid block · arrow · tetrahedral set
--------------------------------------------------------------------------- */

const UP = new THREE.Vector3(0, 1, 0);
const BLUE = 0x7aa8dd, RED = 0xe08a8a, ORANGE = 0xf5b352, AXC = 0x111111, GREY = 0x9a9a9a, GUIDE = 0xb4b4b4;
function CHEM(x, y, z) { return new THREE.Vector3(x, z, -y); }   // chem(x,y,z) → world

const VIEW = { projection: 'oblique', obliqueAngleDeg: 35, depthScale: 0.60 };
const HF = { all: 0.94, atomic: 0.86, mix: 0.86, hybrid: 0.86, tetra: 0.72 };

const PL = 1.9, COMB_L = 2.3;
const AX = [-11.2, -6.2], RY = [2.5, -2.5], HX = [2.4, 7.4];
const COMB_OFF = new THREE.Vector3((HX[0] + HX[1]) / 2, -12.0, 0);

/* lights (belt & braces — all surface colour is baked into vertex colours) */
scene.add(new THREE.AmbientLight(0xffffff, 1.0));

/* ---------- baked shading (light-independent, MeshBasic + vertexColors) --- */
const LIGHTV = new THREE.Vector3(-0.40, 0.62, 0.68).normalize();
function shade(geo, hex) {
  const col = new THREE.Color(hex);
  const nrm = geo.attributes.normal;
  const n = nrm.count, arr = new Float32Array(n * 3), v = new THREE.Vector3();
  for (let i = 0; i < n; i++) {
    v.fromBufferAttribute(nrm, i);
    const dd = Math.max(0, v.dot(LIGHTV));
    const f = 0.58 + 0.42 * Math.pow(dd, 0.75);
    const hl = 0.22 * Math.pow(dd, 7);
    arr[i * 3] = Math.min(1, col.r * f + hl);
    arr[i * 3 + 1] = Math.min(1, col.g * f + hl);
    arr[i * 3 + 2] = Math.min(1, col.b * f + hl);
  }
  geo.setAttribute('color', new THREE.BufferAttribute(arr, 3));
  return geo;
}
function basicMat() {
  return new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.DoubleSide, transparent: false, opacity: 1 });
}
function setMats(mats, o) {
  const oo = Math.min(1, Math.max(0, o));
  for (const m of mats) {
    m.visible = oo > 0.015;
    m.opacity = oo;
    const t = oo < 0.995;
    if (m.transparent !== t) { m.transparent = t; m.needsUpdate = true; }
  }
}
function setOp(e, o) { if (e) e.div.style.opacity = String(o); }
function removeLabel(e) { if (!e) return; e.div.remove(); const i = _labels.indexOf(e); if (i >= 0) _labels.splice(i, 1); }
function disposeTree(o) {
  o.traverse(c => {
    c.geometry?.dispose?.();
    if (Array.isArray(c.material)) c.material.forEach(m => m.dispose?.());
    else c.material?.dispose?.();
  });
}

/* ---------- primitives ---------- */
function lobeProfile(len, halfW) {
  const seg = 44, pts = [];
  for (let i = 0; i <= seg; i++) {
    const t = i / seg;
    const r = halfW * Math.pow(Math.sin(Math.PI * t), 0.95) * Math.pow(t, 0.45);
    pts.push(new THREE.Vector2(Math.max(r, 0.0012), len * t));
  }
  return new THREE.LatheGeometry(pts, 46);
}
function lobeMesh(dir, len, halfW, hex) {
  const g = lobeProfile(len, halfW);
  g.applyQuaternion(new THREE.Quaternion().setFromUnitVectors(UP, dir.clone().normalize()));
  shade(g, hex);
  return new THREE.Mesh(g, basicMat());
}
function sphereMesh(r, hex) {
  return new THREE.Mesh(shade(new THREE.SphereGeometry(r, 40, 26), hex), basicMat());
}
function orient(mesh, dir) { mesh.quaternion.setFromUnitVectors(UP, dir.clone().normalize()); return mesh; }

function makeTriad(L) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color: AXC, transparent: false, opacity: 1 });
  [CHEM(1, 0, 0), CHEM(0, 1, 0), CHEM(0, 0, 1)].forEach(dir => {
    const cyl = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 2 * L, 12), mat);
    orient(cyl, dir); g.add(cyl);
    const tip = new THREE.Mesh(new THREE.ConeGeometry(0.105, 0.30, 18), mat);
    tip.position.copy(dir).multiplyScalar(L + 0.06); orient(tip, dir); g.add(tip);
  });
  return { group: g, mats: [mat] };
}

function blockArrow(from, dir, len) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color: GREY, transparent: false, opacity: 1 });
  const dd = dir.clone().normalize();
  const sh = len * 0.66, hd = len * 0.34;
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.13, sh, 14), mat);
  shaft.position.copy(dd).multiplyScalar(sh / 2); orient(shaft, dd); g.add(shaft);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.32, hd, 20), mat);
  head.position.copy(dd).multiplyScalar(sh + hd / 2); orient(head, dd); g.add(head);
  g.position.copy(from);
  return { group: g, mats: [mat] };
}

function arcPoints(a, b, r, n) {
  const d0 = a.clone().normalize(), d1 = b.clone().normalize();
  let axis = new THREE.Vector3().crossVectors(d0, d1);
  if (axis.lengthSq() < 1e-8) axis = new THREE.Vector3(0, 1, 0).cross(d0);
  axis.normalize();
  const ang = d0.angleTo(d1), pts = [];
  for (let i = 0; i <= n; i++) {
    const q = new THREE.Quaternion().setFromAxisAngle(axis, ang * i / n);
    pts.push(d0.clone().applyQuaternion(q).multiplyScalar(r));
  }
  return pts;
}

/* ---------- labels ---------- */
const SER = 'font-family:Georgia,\'Times New Roman\',serif';
function ital(t) { return '<i style="' + SER + '">' + t + '</i>'; }
function triadLabels(off, L, fs) {
  return [
    addLabel(ital('x'), off.clone().add(CHEM(1, 0, 0).multiplyScalar(L + 0.22)), { fontSize: fs, offset: [13, 4] }),
    addLabel(ital('y'), off.clone().add(CHEM(0, 1, 0).multiplyScalar(L + 0.20)), { fontSize: fs, offset: [13, -7] }),
    addLabel(ital('z'), off.clone().add(CHEM(0, 0, 1).multiplyScalar(L + 0.22)), { fontSize: fs, offset: [5, -12] })
  ];
}

/* ---------- state / model ---------- */
const state = {
  stage: 'all', morph: 1, morphTarget: 1,
  showS: true, showPx: true, showPy: true, showPz: true,
  showAngle: false, showHybLbl: false, selected: null
};
const PNAME = ['<i>p<sub>x</sub></i>', '<i>p<sub>y</sub></i>', '<i>p<sub>z</sub></i>'];
const PPLAIN = ['px', 'py', 'pz'];
const S3 = (function () {
  const out = [[0, 0, 1]];
  [60, 180, 300].forEach(A => {
    const a = THREE.MathUtils.degToRad(A), c = Math.sqrt(8) / 3;
    out.push([c * Math.cos(a), c * Math.sin(a), -1 / 3]);
  });
  return out;
})();

function buildModel() {
  const axes = [];
  if (state.showPx) axes.push([1, 0, 0]);
  if (state.showPy) axes.push([0, 1, 0]);
  if (state.showPz) axes.push([0, 0, 1]);
  const n = axes.length;
  if (!state.showS && n === 0)
    return { type: 'none', n: 0, dirs: [], label: 'nothing selected', angle: null, note: 'Tick at least one orbital to mix.' };
  if (!state.showS)
    return {
      type: 'p', n, dirs: axes,
      label: (n === 1 ? 'one' : n === 2 ? 'two' : 'three') + ' unhybridized <i>p</i> orbital' + (n > 1 ? 's' : ''),
      angle: n > 1 ? 90 : null,
      note: 'No s orbital → no hybridization. Mixing p orbitals with each other only rotates the set: the lobes stay 90° apart and keep pure p character.'
    };
  if (n === 0)
    return { type: 's', n: 0, dirs: [[0, 0, 1]], label: 'unhybridized <i>s</i> orbital', angle: null, note: 'A lone s orbital is spherical — no direction, nothing to hybridize.' };
  if (n === 1) {
    const u = axes[0];
    return {
      type: 'sp', n: 1, dirs: [u, u.map(v => -v)], label: 'two <i>sp</i> hybrid orbitals', angle: 180,
      note: 's + one p → two sp hybrids 180° apart: a linear arrangement, as in HC≡CH.'
    };
  }
  if (n === 2) {
    const u = axes[0], v = axes[1], d = [];
    for (let k = 0; k < 3; k++) {
      const th = k * 2 * Math.PI / 3;
      d.push([0, 1, 2].map(j => Math.cos(th) * u[j] + Math.sin(th) * v[j]));
    }
    return {
      type: 'sp2', n: 2, dirs: d, label: 'three <i>sp</i><sup>2</sup> hybrid orbitals', angle: 120,
      note: 's + two p → three sp² hybrids 120° apart in the plane of those p orbitals: trigonal planar, as in BF₃.'
    };
  }
  return {
    type: 'sp3', n: 3, dirs: S3.map(a => a.slice()),
    label: 'four <i>sp</i><sup>3</sup> hybrid orbitals', angle: 109.47,
    note: 's + three p → four equivalent sp³ hybrids aimed at the corners of a tetrahedron, 109.5° apart, as in CH₄.'
  };
}
let MODEL = buildModel();
function angleText() { return MODEL.angle === null ? '' : (MODEL.angle === 109.47 ? '109.5°' : MODEL.angle + '°'); }
function coefStr(c) { return Math.abs(c).toFixed(3).replace(/0+$/, '').replace(/\.$/, ''); }
function formulaHTML(i, plain) {
  const P = plain ? PPLAIN : PNAME, IS = plain ? 's' : '<i>s</i>';
  if (MODEL.type === 'p') return P[MODEL.dirs[i].findIndex(v => Math.abs(v) > 0.5)] + ' (unhybridized)';
  if (MODEL.type === 's') return IS + ' (unhybridized)';
  const n = MODEL.n, cs = 1 / Math.sqrt(1 + n), cp = Math.sqrt(n / (1 + n));
  const dir = MODEL.dirs[i];
  let s = (plain ? 'h' + (i + 1) : '<i>h</i><sub>' + (i + 1) + '</sub>') + ' = ' + coefStr(cs) + ' ' + IS;
  for (let k = 0; k < 3; k++) {
    const c = cp * dir[k];
    if (Math.abs(c) > 1e-4) s += (c > 0 ? ' + ' : (plain ? ' - ' : ' &minus; ')) + coefStr(c) + ' ' + P[k];
  }
  return s;
}

/* ---------- atomic block (fixed, matches the source 2×2) ---------- */
const atomicGroup = new THREE.Group();
const ATOM_DEF = [
  { kind: 's', cap: ital('s'), key: 'showS', slot: [AX[0], RY[0]] },
  { kind: 'px', cap: ital('p') + '<i style="' + SER + ';font-size:0.78em">x</i>', key: 'showPx', slot: [AX[1], RY[0]] },
  { kind: 'py', cap: ital('p') + '<i style="' + SER + ';font-size:0.78em">y</i>', key: 'showPy', slot: [AX[0], RY[1]] },
  { kind: 'pz', cap: ital('p') + '<i style="' + SER + ';font-size:0.78em">z</i>', key: 'showPz', slot: [AX[1], RY[1]] }
];
const atomicPanels = ATOM_DEF.map(def => {
  const off = new THREE.Vector3(def.slot[0], def.slot[1], 0);
  const g = new THREE.Group(); g.position.copy(off);
  const tri = makeTriad(PL); g.add(tri.group);
  const mats = tri.mats.slice();
  if (def.kind === 's') {
    const m = sphereMesh(0.42, BLUE); g.add(m); mats.push(m.material);
  } else {
    const ax = def.kind === 'px' ? CHEM(1, 0, 0) : def.kind === 'py' ? CHEM(0, 1, 0) : CHEM(0, 0, 1);
    const a = lobeMesh(ax, 1.70, 0.42, BLUE), b = lobeMesh(ax.clone().negate(), 1.70, 0.42, RED);
    g.add(a); g.add(b); mats.push(a.material, b.material);
  }
  atomicGroup.add(g);
  const labels = triadLabels(off, PL, '16px');
  const cap = addLabel(def.cap, off.clone().add(CHEM(0, 0, -1).multiplyScalar(PL + 0.30)), { fontSize: '19px', offset: [0, 16] });
  return { def, group: g, off, mats, labels, cap };
});

/* ---------- hybrid block (rebuilt from the model) ---------- */
const hybridGroup = new THREE.Group();
const hybPanels = [];
function backRatio(n) { return n <= 0 ? 0 : Math.max(0.16, 0.62 / Math.pow(n, 0.72)); }
function hybridParts(dirW, n) {
  const parts = [], mats = [];
  const Lb = 1.95, W = 0.52, r = backRatio(n);
  const big = lobeMesh(dirW, Lb, W, ORANGE); parts.push(big); mats.push(big.material);
  const back = lobeMesh(dirW.clone().negate(), Lb * r, W * Math.sqrt(r), ORANGE);
  parts.push(back); mats.push(back.material);
  const lm = new THREE.LineBasicMaterial({ color: GUIDE, transparent: false, opacity: 1 });
  const ln = new THREE.Line(new THREE.BufferGeometry().setFromPoints([
    dirW.clone().multiplyScalar(-Lb * r - 0.55), dirW.clone().multiplyScalar(Lb + 0.45)]), lm);
  parts.push(ln); mats.push(lm);
  return { parts, mats, big };
}
function pureParts(dirW) {
  const a = lobeMesh(dirW, 1.70, 0.42, BLUE), b = lobeMesh(dirW.clone().negate(), 1.70, 0.42, RED);
  return { parts: [a, b], mats: [a.material, b.material], big: a };
}
function hybSlots(k) {
  const cx = (HX[0] + HX[1]) / 2;
  if (k <= 1) return [new THREE.Vector3(cx, 0, 0)];
  if (k === 2) return [new THREE.Vector3(HX[0], 0, 0), new THREE.Vector3(HX[1], 0, 0)];
  if (k === 3) return [new THREE.Vector3(HX[0], RY[0], 0), new THREE.Vector3(HX[1], RY[0], 0), new THREE.Vector3(cx, RY[1], 0)];
  return [new THREE.Vector3(HX[0], RY[0], 0), new THREE.Vector3(HX[1], RY[0], 0),
  new THREE.Vector3(HX[0], RY[1], 0), new THREE.Vector3(HX[1], RY[1], 0)];
}
function rebuildHybrids() {
  hybPanels.forEach(p => { p.labels.forEach(removeLabel); removeLabel(p.cap); });
  [...hybridGroup.children].forEach(c => { hybridGroup.remove(c); disposeTree(c); });
  hybPanels.length = 0;
  if (MODEL.type === 'none') return;
  const slots = hybSlots(MODEL.dirs.length);
  MODEL.dirs.forEach((dc, i) => {
    const off = slots[i] || new THREE.Vector3();
    const g = new THREE.Group(); g.position.copy(off);
    const tri = makeTriad(PL); g.add(tri.group);
    let dirW = null, part;
    if (MODEL.type === 's') {
      const m = sphereMesh(0.48, ORANGE); part = { parts: [m], mats: [m.material], big: m };
    } else {
      dirW = CHEM(dc[0], dc[1], dc[2]).normalize();
      part = MODEL.type === 'p' ? pureParts(dirW) : hybridParts(dirW, MODEL.n);
    }
    part.parts.forEach(p => g.add(p));
    hybridGroup.add(g);
    const cap = addLabel(MODEL.type === 'p'
      ? PNAME[dc.findIndex(v => Math.abs(v) > 0.5)]
      : '<i>h</i><sub>' + (i + 1) + '</sub>',
      off.clone().add(CHEM(0, 0, -1).multiplyScalar(PL + 0.30)), { fontSize: '17px', color: '#7a4a00', offset: [0, 16] });
    hybPanels.push({
      group: g, off, dir: dirW, idx: i, orbMats: part.mats, triMats: tri.mats,
      labels: triadLabels(off, PL, '16px'), cap
    });
  });
}

/* ---------- combined (tetrahedral) view ---------- */
const combinedGroup = new THREE.Group();
combinedGroup.position.copy(COMB_OFF);
const combTri = makeTriad(COMB_L); combinedGroup.add(combTri.group);
const combDot = new THREE.Mesh(shade(new THREE.SphereGeometry(0.075, 14, 10), 0x111111), basicMat());
combinedGroup.add(combDot);
const combParts = [];
let angleArc = null;
const combLabels = triadLabels(COMB_OFF, COMB_L, '17px');
const combAngleLbl = addLabel('', COMB_OFF.clone(), { fontSize: '15px', color: '#222', bold: true, background: 'rgba(255,255,255,0.88)' });

function rebuildCombined() {
  combParts.forEach(h => { h.parts.forEach(p => { combinedGroup.remove(p); disposeTree(p); }); });
  combParts.length = 0;
